<script setup lang="ts">
import {ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {api,ApiError} from '../api';
import type {WorkTab} from '../stores';
import Modal from '../components/Modal.vue';
import PromotionPositionSelect from '../components/PromotionPositionSelect.vue';
type Draft={employee_code:string;employee_name:string;position:string;newbie_level:string;effective_date:string;notes:string};
const props=defineProps<{tab:WorkTab}>();
const empty=():Draft=>({employee_code:'',employee_name:'',position:'',newbie_level:'',effective_date:'',notes:''});
const rows=ref<Draft[]>([empty()]),data=ref<any>(null),errors=ref<any[]>([]),error=ref(''),message=ref(''),loading=ref(false),checking=ref(false),confirm=ref(false),imported=ref<any>(null),expected=ref(''),dups=ref<any[]>([]);
let baseline=JSON.stringify(rows.value),pendingKey='',requestId='',resolver:((ok:boolean)=>void)|null=null;
const endpoint='store-promotions?store='+encodeURIComponent(props.tab.store);
watch(rows,()=>{props.tab.dirty=JSON.stringify(rows.value)!==baseline;expected.value='';errors.value=[];message.value='';},{deep:true,flush:'sync'});
async function load(){loading.value=true;error.value='';try{data.value=await api(endpoint);props.tab.title='批次升遷 · '+data.value.store.store_name;}catch(e){data.value=null;error.value=(e as Error).message;}finally{loading.value=false;}}
function positionChanged(row:Draft){row.newbie_level='';}
function applyImport(result:any){rows.value=result.rows;errors.value=result.errors;expected.value=result.expected||'';dups.value=result.duplicates||[];imported.value=null;message.value=`已載入 ${rows.value.length} 筆，尚未儲存。`;}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;checking.value=true;error.value='';try{const form=new FormData();form.append('file',file);const result=await api(endpoint,{method:'POST',body:form});if(props.tab.dirty)imported.value=result;else applyImport(result);}catch(e){error.value=(e as Error).message;}finally{checking.value=false;}}
async function validate(){if(!data.value||checking.value||props.tab.busy)return false;checking.value=true;error.value='';message.value='';try{const result=await api(endpoint,{method:'POST',body:JSON.stringify({operation:'validate',rows:rows.value})});rows.value=result.rows;errors.value=result.errors;expected.value=result.expected||'';dups.value=result.duplicates||[];if(result.valid)message.value=`${rows.value.length} 筆資料驗證通過${dups.value.length?`（其中 ${dups.value.length} 筆已存在，將自動略過）`:''}，尚未儲存。`;return result.valid;}catch(e){error.value=(e as Error).message;return false;}finally{checking.value=false;}}
function answer(ok:boolean){confirm.value=false;resolver?.(ok);resolver=null;}
async function save(){if(!data.value||props.tab.busy||loading.value||checking.value||confirm.value||imported.value)return false;if(!expected.value&&!await validate())return false;
const ok=await new Promise<boolean>(resolve=>{resolver=resolve;confirm.value=true;});if(!ok)return false;
props.tab.busy=true;error.value='';const key=JSON.stringify(rows.value);if(key!==pendingKey){pendingKey=key;requestId=crypto.randomUUID();}
try{const result=await api(endpoint,{method:'POST',body:JSON.stringify({operation:'save',rows:rows.value,expected:expected.value,requestId})});rows.value=[empty()];baseline=JSON.stringify(rows.value);props.tab.dirty=false;expected.value='';pendingKey='';dups.value=[];message.value=`已儲存 ${result.created} 筆升遷，已同步 ${result.monthlyUpdated} 筆月份資料。${result.skipped?.length?`另有 ${result.skipped.length} 筆已存在且內容完全相同，已自動略過：${result.skipped.map((s:any)=>s.employee_code+' '+s.effective_date+' '+s.position).join('、')}。`:''}`;return true;}catch(e){error.value=(e as Error).message;if(e instanceof ApiError&&e.status===409)expected.value='';return false;}finally{props.tab.busy=false;}}
props.tab.save=save;onMounted(load);onBeforeUnmount(()=>{answer(false);delete props.tab.save;});
</script>
<template>
<header class="page-heading"><div><p class="eyebrow">組織與門市 / 門市升遷管理</p><h1>批次升遷</h1><p v-if="data" class="muted">{{data.store.store_code}} {{data.store.store_name}}</p></div><button @click="load" :disabled="loading||checking||tab.busy||confirm||!!imported">重新載入設定</button></header>
<p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><p v-if="loading" role="status">載入升遷設定…</p>
<template v-if="data"><p class="muted">依生效月份更新職位，保留後續升遷。未來職位會在生效日自動更新員工主檔；代理店長只標示暫代，不取代正式職位。</p>
<fieldset :disabled="loading||checking||tab.busy||confirm||!!imported"><div class="module-actions"><a class="template-link" :href="'/api/workspace/'+endpoint+'&template=true'" download>下載 Excel 範本</a><label class="upload">匯入 Excel<input type="file" accept=".xlsx,.xls" @change="upload"></label><button @click="rows.push(empty())" :disabled="rows.length>=500">新增列</button></div>
<p v-if="checking" role="status">驗證資料中…</p><div v-if="dups.length&&!errors.length" class="notice" role="status"><strong>{{dups.length}} 筆已存在且內容完全相同，儲存時自動略過</strong><ul><li v-for="(d,i) in dups" :key="i">第 {{d.row}} 列：{{d.employee_code}}　{{d.message}}</li></ul></div><div v-if="errors.length" class="notice error" role="alert"><strong>請修正 {{errors.length}} 項問題</strong><ul><li v-for="(issue,i) in errors" :key="i">第 {{issue.row}} 列：{{issue.message}}</li></ul></div>
<div class="promotion-rows"><section v-for="(row,i) in rows" :key="i" class="promotion-row" :aria-label="`升遷第 ${i+1} 列`"><header><h2>第 {{i+1}} 筆</h2><button class="danger" :disabled="rows.length===1" @click="rows.splice(i,1)">刪除此列</button></header><div class="promotion-fields"><label>員編<input v-model="row.employee_code" maxlength="20" autocomplete="off"></label><label>姓名<input v-model="row.employee_name" maxlength="100" autocomplete="off"></label><PromotionPositionSelect v-model="row.position" :positions="data.positions" title="職位" placeholder="請選擇職位" @change="positionChanged(row)"/><label v-if="row.position==='新人'||row.position==='行政'">{{row.position==='新人'?'新人階段':'行政階級'}}<select :aria-label="row.position==='新人'?'新人階段':'行政階級'" v-model="row.newbie_level"><option value="">請選擇</option><option v-for="option in row.position==='新人'?data.newbieLevels:data.adminLevels" :key="option.value" :value="option.value">{{option.label}}</option></select></label><label>生效日<input type="date" min="1912-01-01" v-model="row.effective_date"></label><label class="notes">備註<textarea v-model="row.notes" maxlength="5000" rows="2"></textarea></label></div></section></div>
<div class="dialog-actions"><span>{{rows.length}} 筆，最多 500 筆</span><button @click="validate">驗證資料</button><button class="primary" @click="save" :disabled="!tab.dirty">{{tab.busy?'儲存中…':'儲存升遷紀錄'}}</button></div></fieldset></template>
<Modal v-if="confirm" title="確認批次升遷" @cancel="answer(false)"><p>即將為 {{data.store.store_name}} 新增 {{rows.length}} 筆升遷紀錄，並同步這些員工生效月份起的職位資料（包含調店後月份）。</p><p>歷程與月份同步會一起儲存；後續已有升遷的月份會依時間順序保留。</p><div class="dialog-actions"><button @click="answer(false)">返回核對</button><button class="primary" @click="answer(true)">確認儲存</button></div></Modal>
<Modal v-if="imported" title="取代目前升遷草稿" @cancel="imported=null"><p>Excel 有 {{imported.rows.length}} 筆資料。匯入會取代目前 {{rows.length}} 筆尚未儲存的草稿。</p><div class="dialog-actions"><button @click="imported=null">保留目前草稿</button><button class="primary" @click="applyImport(imported)">載入 Excel 資料</button></div></Modal>
</template>
<style scoped>fieldset{border:0;padding:0;min-width:0}.template-link{text-decoration:underline;padding:10px 0}.upload{display:flex;align-items:center;gap:12px}.upload input{max-width:260px}.promotion-row{border-block-start:1px solid var(--line);padding:20px 0}.promotion-row header{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.promotion-row h2{font-size:16px;margin:0}.promotion-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.promotion-fields label{display:grid;gap:8px}.promotion-fields input,.promotion-fields select,.promotion-fields textarea{min-width:0;width:100%}.notes{grid-column:span 2}.promotion-rows{margin-top:24px}.notice ul{max-height:260px;overflow:auto;line-height:1.8}@media(max-width:800px){.promotion-fields{grid-template-columns:1fr 1fr}}@media(max-width:450px){.promotion-fields{grid-template-columns:1fr}.notes{grid-column:auto}.upload{flex-wrap:wrap}}</style>
